import json
from base64 import b64encode
from .exceptions import CertificateInstallationFailure


class NodeOam(object):
    DEFAULT_FAN_STATUS = 'EStatus_NoError'
    DEFAULT_FAN_SPEED = 4300
    _configured = None

    def __init__(self, session):
        self.session = session

    def put_fsm_clic(self, payload, fsm_id='1'):
        url = '/mz/p/v1/pbts/1/fsm/{}/clic'.format(fsm_id)
        payload = json.dumps(payload)
        return self.session.send_request(url=url, method='PUT', data=payload)

    def set_temperatures(self, sensor_group_type, sensor_id_to_temperature):
        url = '/mz/p/v1/clic/setTemperatures'
        payload = self._process_sensor_id_to_temperature(
            sensor_group_type, sensor_id_to_temperature)
        payload = json.dumps(payload)
        return self.session.send_request(url=url, method='PUT', data=payload)

    def _process_sensor_id_to_temperature(self, sensor_group_type,
                                          sensor_id_to_temperature):
        sensors = []
        for sensor_name in sensor_id_to_temperature.keys():
            sensors.append(
                {"sensorId": sensor_name,
                 "temperature": sensor_id_to_temperature[sensor_name]})
        return {"sensorType": sensor_group_type, "sensors": sensors}

    def set_fan_speeds(self, fan1_speed, fan1_status, fan2_speed, fan2_status):
        payload = {
            "FsmFan1_speed": fan1_speed or self.DEFAULT_FAN_SPEED,
            "FsmFan1_status": fan1_status or self.DEFAULT_FAN_STATUS,
            "FsmFan2_speed": fan2_speed or self.DEFAULT_FAN_SPEED,
            "FsmFan2_status": fan2_status or self.DEFAULT_FAN_STATUS,
        }
        url = '/mz/p/v1/clic/setFanSpeeds'
        payload = json.dumps(payload)
        return self.session.send_request(url=url, method='PUT', data=payload)

    def set_fsm_temperature_test_mode(self, enter_testmode, fsm_id='1'):
        """
        :param enter_testmode: Accepts values True or False. True will activate
            the test mode, False will deactivate it. Value can be a boolean or
            string.
        :param fsm_id: id of system module
        :return:
        """
        state = bool(enter_testmode)
        payload = {'testMode': state}
        return self.put_fsm_clic(payload, fsm_id)

    def set_fsm_fan_test_mode(self, enter_testmode, fsm_id='1'):
        """
        :param enter_testmode: Accepts values True or False. True will activate
            the test mode, False will deactivate it. Value can be a boolean or
            string.
        :param fsm_id: id of system module
        :return:
        """
        state = bool(enter_testmode)
        payload = {'fantestMode': state}
        return self.put_fsm_clic(payload, fsm_id)

    def _get_given_module_ids(self, module_name):
        """
        :param string module_name: possible modules: fsm, fbb, frm, rtm
        :return: list with numbers of existing module(s) of type 'module_name'
        """
        url = '/mz/p/v1/pbts/1'
        resp = self.session.send_request(url)
        return list(resp.json()[module_name].keys())

    def get_fbb(self, attribute=None, fbb_id='1'):
        url = '/mz/p/v1/pbts/1/fbb/{}'.format(fbb_id)
        resp = self.session.send_request(url)
        fbb_json = resp.json()
        return fbb_json[attribute] if attribute is not None else fbb_json

    def get_fsp(self, attribute=None, fbb_id=None):
        if fbb_id is not None:
            return self._get_fsps_by_id(attribute, fbb_id)

        fbb = {}
        for fbb_id in self._get_given_module_ids('fbb'):
            fbb[fbb_id] = self._get_fsps_by_id(attribute, fbb_id)
        return fbb

    def _get_fsps_by_id(self, attribute, fbb_id):
        url = '/mz/p/v1/pbts/1/fbb/{}/fsp'.format(fbb_id)
        resp = self.session.send_request(url)
        return resp.json()[attribute] if attribute is not None else resp.json()

    def get_fsm(self, attribute=None, fsm_id='1'):
        url = '/mz/p/v1/pbts/1/fsm/{}'.format(fsm_id)
        resp = self.session.send_request(url)
        fsm_json = resp.json()
        return fsm_json[attribute] if attribute is not None else fsm_json

    def get_fct(self, attribute=None, fsm_id=None):
        if fsm_id is not None:
            return self._get_fcts_by_id(attribute, fsm_id)

        fsm = {}
        for fsm_id in self._get_given_module_ids('fsm'):
            fsm[fsm_id] = self._get_fcts_by_id(attribute, fsm_id)
        return fsm

    def _get_fcts_by_id(self, attribute, fsm_id):
        url = '/mz/p/v1/pbts/1/fsm/{}/fct'.format(fsm_id)
        resp = self.session.send_request(url)
        return resp.json()[attribute] if attribute is not None else resp.json()

    def get_fsp_sensors_names(self, fbb_id):
        url = '/mz/p/v1/pbts/1/fbb/{}/fsp/sensors'.format(fbb_id)
        resp = self.session.send_request(url).json()
        sensors = []
        for sensor_id in resp.keys():
            sensors.append(resp[sensor_id]['id']['name'])
        return sensors

    def set_sensors_fault_state(self, sensor_group_type, sensors_parameters):
        url = '/mz/p/v1/clic/setTemperatures'
        payload = self._process_sensors_parameters(sensor_group_type,
                                                   sensors_parameters)
        payload = json.dumps(payload)
        return self.session.send_request(url=url, method='PUT', data=payload)

    def _process_sensors_parameters(self, sensor_group_type,
                                    sensors_parameters):
        sensors = []
        for name, value in sensors_parameters.items():
            sensors.append(
                {'sensorId': name,
                 'temperature': value['temperature'],
                 'temp_sensor_state': value['temp_sensor_state'],
                 'i2c_fault_id': value['i2c_fault_id']})
        return {"sensorType": sensor_group_type, "sensors": sensors}

    def install_certificate(self, pkcs_data, password):
        """
        Send a pkcs12 file to nodeoam for certificate installation.

        :param bytes pkcs_data: bytestring-data from the pkcs file
        :param string password: (optional) password for the pkcs data
        """
        url = '/api/v1/certMgmt/executeCommand'
        command = "replaceNeKeyChainPKCS"
        pkcs_base64 = b64encode(pkcs_data)

        payload = {
            'operation': command,
            'params': {
                'pkcs12': pkcs_base64.decode('ascii'),
                'passwd': password
            },
            'target': ['']
        }
        response = self.session.send_request(url, method='PUT', json=payload)

        if response.status_code != 200:
            exc_msg = "Bad response {}".format(response.status_code)
            raise CertificateInstallationFailure(exc_msg)
